   <div id="app"></div>

   <script>
     const quizQuestions = [
       {
         id: "question-1",
         title: "Which of these are programming languages commonly used for web development?",
         helpText: "Select every answer that fits. More than one choice is correct.",
         options: ["JavaScript", "Python", "HTML", "Ruby"]
       },
       {
         id: "question-2",
         title: "Which languages are primarily associated with systems or performance-focused programming?",
         options: ["C", "Rust", "Go", "CSS"]
       },
       {
         id: "question-3",
         title: "Which of these languages are typically used in mobile app development?",
         options: ["Swift", "Kotlin", "Java", "SQL"]
       }
     ];

     function createElement(tag, className, text) {
       const element = document.createElement(tag);
       if (className) {
         element.className = className;
       }
       if (text) {
         element.textContent = text;
       }
       return element;
     }

     function OptionCheckbox(questionId, option, optionIndex) {
       const label = createElement("label", "option-card");
       const input = document.createElement("input");
       input.type = "checkbox";
       input.name = questionId;
       input.value = option;
       input.id = questionId + "-option-" + optionIndex;

       const text = createElement("span", "option-text", option);

       label.htmlFor = input.id;
       label.append(input, text);
       return label;
     }

     function QuizQuestion(question, index) {
       const field = createElement("div", "form-field");

       const header = createElement("div", "field-header");
       const badge = createElement("div", "field-index", String(index + 1));
       const copy = createElement("div");
       const title = createElement("h2", "field-title", question.title);
       copy.appendChild(title);

       if (question.helpText) {
         copy.appendChild(createElement("p", "field-help", question.helpText));
       }

       header.append(badge, copy);

       const options = createElement("div", "options");
       question.options.forEach((option, optionIndex) => {
         options.appendChild(OptionCheckbox(question.id, option, optionIndex));
       });

       field.append(header, options);
       return field;
     }

     function ResultPanel() {
       const panel = createElement("div", "result-panel");
       panel.hidden = true;
       panel.setAttribute("aria-live", "polite");
       panel.id = "result-panel";
       return panel;
     }

     function QuizForm() {
       const form = createElement("form", "quiz-form");
       form.noValidate = true;

       const grid = createElement("div", "form-grid");
       quizQuestions.forEach((question, index) => {
         grid.appendChild(QuizQuestion(question, index));
       });

       const actions = createElement("div", "form-actions");
       const note = createElement("p", "selection-note", "Every question supports multiple selections.");
       const submit = createElement("button", "submit-button", "Submit quiz");
       submit.type = "submit";

       actions.append(note, submit);
       form.append(grid, actions, ResultPanel());

       form.addEventListener("submit", function (event) {
         event.preventDefault();

         const selections = quizQuestions.map(function (question) {
           const checked = Array.from(form.querySelectorAll('input[name="' + question.id + '"]:checked'))
             .map(function (input) {
               return input.value;
             });

           return {
             title: question.title,
             answers: checked
           };
         });

         const resultPanel = form.querySelector("#result-panel");
         resultPanel.hidden = false;
         resultPanel.innerHTML = "";

         const heading = createElement("h2", null, "Selections submitted");
         const summary = createElement("p", null, "Here is a quick summary of the answers you selected:");
         const list = document.createElement("ul");

         selections.forEach(function (selection) {
           const item = document.createElement("li");
           item.textContent = selection.title + " — " + (selection.answers.length ? selection.answers.join(", ") : "No answers selected");
           list.appendChild(item);
         });

         resultPanel.append(heading, summary, list);
       });

       return form;
     }

     function App() {
       const shell = createElement("main", "page-shell");
       const card = createElement("section", "quiz-card");

       const hero = createElement("header", "quiz-hero");
       const eyebrow = createElement("div", "eyebrow", "Interactive quiz");
       const title = createElement("h1", null, "Explore computer languages");
       const copy = createElement(
         "p",
         "hero-copy",
         "Answer three multi-select questions about languages used across the web, systems programming, and mobile development."
       );

       hero.append(eyebrow, title, copy);
       card.append(hero, QuizForm());
       shell.appendChild(card);
       return shell;
     }

     document.getElementById("app").appendChild(App());
   </script>
 </body>
 </html>

