  <script>
    const quizQuestions = [
      {
        id: "question-1",
        title: "Which of these are programming languages commonly used for web development?",
        helpText: "Select every answer that fits. More than one choice is correct.",
        options: ["JavaScript", "Python", "HTML", "Ruby"]
      },
      {
        id: "question-2",
        title: "Which languages are primarily associated with systems or performance-focused programming?",
        options: ["C", "Rust", "Go", "CSS"]
      },
      {
        id: "question-3",
        title: "Which of these languages are typically used in mobile app development?",
        options: ["Swift", "Kotlin", "Java", "SQL"]
      }
    ];

    function escapeHtml(value) {
      return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    function OptionCheckbox(questionId, option, optionIndex) {
      const inputId = questionId + "-option-" + optionIndex;
      return `
        <label class="option-card" for="${escapeHtml(inputId)}">
          <input type="checkbox" name="${escapeHtml(questionId)}" value="${escapeHtml(option)}" id="${escapeHtml(inputId)}">
          <span class="option-text">${escapeHtml(option)}</span>
        </label>
      `;
    }

    function QuizQuestion(question, index) {
      const helpMarkup = question.helpText
        ? `<p class="field-help">${escapeHtml(question.helpText)}</p>`
        : "";

      return `
        <div class="form-field">
          <div class="field-header">
            <div class="field-index">${index + 1}</div>
            <div>
              <h2 class="field-title">${escapeHtml(question.title)}</h2>
              ${helpMarkup}
            </div>
          </div>
          <div class="options">
            ${question.options.map(function (option, optionIndex) {
              return OptionCheckbox(question.id, option, optionIndex);
            }).join("")}
          </div>
        </div>
      `;
    }

    function ResultPanel() {
      return '<div class="result-panel" id="result-panel" aria-live="polite" hidden></div>';
    }

    function QuizForm() {
      return `
        <form class="quiz-form" novalidate>
          <div class="form-grid">
            ${quizQuestions.map(function (question, index) {
              return QuizQuestion(question, index);
            }).join("")}
          </div>
          <div class="form-actions">
            <p class="selection-note">Every question supports multiple selections.</p>
            <button class="submit-button" type="submit">Submit quiz</button>
          </div>
          ${ResultPanel()}
        </form>
      `;
    }

    function App() {
      return `
        <main class="page-shell">
          <section class="quiz-card">
            <header class="quiz-hero">
              <div class="eyebrow">Interactive quiz</div>
              <h1>Explore computer languages</h1>
              <p class="hero-copy">Answer three multi-select questions about languages used across the web, systems programming, and mobile development.</p>
            </header>
            ${QuizForm()}
          </section>
        </main>
      `;
    }

    document.getElementById("app").innerHTML = App();

    document.querySelector(".quiz-form").addEventListener("submit", function (event) {
      event.preventDefault();

      const selections = quizQuestions.map(function (question) {
        const checked = Array.from(document.querySelectorAll('input[name="' + question.id + '"]:checked'))
          .map(function (input) {
            return input.value;
          });

        return {
          title: question.title,
          answers: checked
        };
      });

      const resultPanel = document.getElementById("result-panel");
      resultPanel.hidden = false;
      resultPanel.innerHTML = `
        <h2>Selections submitted</h2>
        <p>Here is a quick summary of the answers you selected:</p>
        <ul>
          ${selections.map(function (selection) {
            const answerText = selection.answers.length ? selection.answers.join(", ") : "No answers selected";
            return `<li>${escapeHtml(selection.title)} - ${escapeHtml(answerText)}</li>`;
          }).join("")}
        </ul>
      `;
    });
  </script>
</body>
